/**
 * F03: gRPC peer adapter to REST/GraphQL. Every RPC delegates to the same F01
 * Application Services, so the ownership boundary, idempotency seam and
 * reference-data cache are enforced exactly once across all transports.
 */
export interface PaymentService {
  GetCliente(request: GetClienteRequest): Promise<ClientePerfil>;
  GetCatalogo(request: GetCatalogoRequest): Promise<CatalogoInstitucion>;
  GetQrStatus(request: GetStatusRequest): Promise<JsonResponse>;
  GetTelefonicoStatus(request: GetStatusRequest): Promise<JsonResponse>;
  CreateQr(request: CreateQrRequest): Promise<JsonResponse>;
  CreateTelefonico(request: CreateTelefonicoRequest): Promise<JsonResponse>;
}

export const PaymentServiceServiceName = "tupago.api.v1.PaymentService";
export class PaymentServiceClientImpl implements PaymentService {
  private readonly rpc: Rpc;
  private readonly service: string;
  constructor(rpc: Rpc, opts?: { service?: string }) {
    this.service = opts?.service || PaymentServiceServiceName;
    this.rpc = rpc;
    this.GetCliente = this.GetCliente.bind(this);
    this.GetCatalogo = this.GetCatalogo.bind(this);
    this.GetQrStatus = this.GetQrStatus.bind(this);
    this.GetTelefonicoStatus = this.GetTelefonicoStatus.bind(this);
    this.CreateQr = this.CreateQr.bind(this);
    this.CreateTelefonico = this.CreateTelefonico.bind(this);
  }
  GetCliente(request: GetClienteRequest): Promise<ClientePerfil> {
    const data = GetClienteRequest.encode(request).finish();
    const promise = this.rpc.request(this.service, "GetCliente", data);
    return promise.then((data) => ClientePerfil.decode(new BinaryReader(data)));
  }

  GetCatalogo(request: GetCatalogoRequest): Promise<CatalogoInstitucion> {
    const data = GetCatalogoRequest.encode(request).finish();
    const promise = this.rpc.request(this.service, "GetCatalogo", data);
    return promise.then((data) => CatalogoInstitucion.decode(new BinaryReader(data)));
  }

  GetQrStatus(request: GetStatusRequest): Promise<JsonResponse> {
    const data = GetStatusRequest.encode(request).finish();
    const promise = this.rpc.request(this.service, "GetQrStatus", data);
    return promise.then((data) => JsonResponse.decode(new BinaryReader(data)));
  }

  GetTelefonicoStatus(request: GetStatusRequest): Promise<JsonResponse> {
    const data = GetStatusRequest.encode(request).finish();
    const promise = this.rpc.request(this.service, "GetTelefonicoStatus", data);
    return promise.then((data) => JsonResponse.decode(new BinaryReader(data)));
  }

  CreateQr(request: CreateQrRequest): Promise<JsonResponse> {
    const data = CreateQrRequest.encode(request).finish();
    const promise = this.rpc.request(this.service, "CreateQr", data);
    return promise.then((data) => JsonResponse.decode(new BinaryReader(data)));
  }

  CreateTelefonico(request: CreateTelefonicoRequest): Promise<JsonResponse> {
    const data = CreateTelefonicoRequest.encode(request).finish();
    const promise = this.rpc.request(this.service, "CreateTelefonico", data);
    return promise.then((data) => JsonResponse.decode(new BinaryReader(data)));
  }
}

interface Rpc {
  request(service: string, method: string, data: Uint8Array): Promise<Uint8Array>;
}

type Builtin = Date | Function | Uint8Array | string | number | boolean | bigint | undefined;

export type DeepPartial<T> = T extends bigint ? string | number | bigint
  : T extends Builtin ? T : T extends globalThis.Array<infer U> ? globalThis.Array<DeepPartial<U>>
  : T extends ReadonlyArray<infer U> ? ReadonlyArray<DeepPartial<U>>
  : T extends {} ? { [K in keyof T]?: DeepPartial<T[K]> }
  : Partial<T>;

type KeysOfUnion<T> = T extends T ? keyof T : never;
export type Exact<P, I extends P> = P extends Builtin ? P
  : P & { [K in keyof P]: Exact<P[K], I[K]> } & { [K in Exclude<keyof I, KeysOfUnion<P>>]: never };

function isSet(value: any): boolean {
  return value !== null && value !== undefined;
}

export interface MessageFns<T> {
  encode(message: T, writer?: BinaryWriter): BinaryWriter;
  decode(input: BinaryReader | Uint8Array, length?: number): T;
  fromJSON(object: any): T;
  toJSON(message: T): unknown;
  create<I extends Exact<DeepPartial<T>, I>>(base?: I): T;
  fromPartial<I extends Exact<DeepPartial<T>, I>>(object: I): T;
}
